using Microsoft.CodeAnalysis;
using XMLDocNormalizer.Checks.Infrastructure.Exception.Flow;
using XMLDocNormalizer.Models;
using XMLDocNormalizerTests.Helpers;

namespace XMLDocNormalizerTests.Check.Semantic.Exception
{
    /// <summary>
    /// Tests runtime-target expansion for synchronous and asynchronous
    /// disposal calls generated by using constructs.
    /// </summary>
    public sealed class ExceptionFlowSummaryGraphDisposalDispatchTests
    {
        /// <summary>
        /// Ensures that synchronous disposal through a concrete base type
        /// includes the base implementation and every compatible override.
        /// </summary>
        [Fact]
        public void VirtualDispose_CreatesBaseAndOverrideEdges()
        {
            const string source =
                """
                using System;

                public static class EntryPoint
                {
                    public static void M(BaseResource resource)
                    {
                        using (resource)
                        {
                        }
                    }
                }

                public class BaseResource : IDisposable
                {
                    public virtual void Dispose()
                    {
                        throw new ArgumentException();
                    }
                }

                public sealed class DerivedResource : BaseResource
                {
                    public override void Dispose()
                    {
                        throw new InvalidOperationException();
                    }
                }
                """;

            ExceptionFlowSummaryGraphTestRun run =
                ExceptionFlowSummaryGraphTestHelper.Build(
                    source,
                    "M");

            ExceptionFlowSummaryCallEdge[] edges =
                GetDisposalEdges(run);

            Assert.Equal(
                2,
                edges.Length);

            AssertTargetException(
                run,
                GetEdgeForContainingType(
                    edges,
                    "BaseResource"),
                "ArgumentException");

            AssertTargetException(
                run,
                GetEdgeForContainingType(
                    edges,
                    "DerivedResource"),
                "InvalidOperationException");
        }

        /// <summary>
        /// Ensures that an abstract disposal declaration is not emitted as a
        /// runtime target.
        /// </summary>
        [Fact]
        public void AbstractDispose_ExcludesAbstractTarget()
        {
            const string source =
                """
                using System;

                public static class EntryPoint
                {
                    public static void M(BaseResource resource)
                    {
                        using (resource)
                        {
                        }
                    }
                }

                public abstract class BaseResource : IDisposable
                {
                    public abstract void Dispose();
                }

                public sealed class DerivedResource : BaseResource
                {
                    public override void Dispose()
                    {
                        throw new InvalidOperationException();
                    }
                }
                """;

            ExceptionFlowSummaryGraphTestRun run =
                ExceptionFlowSummaryGraphTestHelper.Build(
                    source,
                    "M");

            ExceptionFlowSummaryCallEdge edge =
                Assert.Single(
                    GetDisposalEdges(run));

            Assert.Equal(
                "DerivedResource",
                GetTargetMethod(edge).ContainingType.Name);

            AssertTargetException(
                run,
                edge,
                "InvalidOperationException");
        }

        /// <summary>
        /// Ensures that the static resource type excludes base and sibling
        /// implementations that cannot receive the runtime value.
        /// </summary>
        [Fact]
        public void DerivedStaticResourceType_ExcludesIncompatibleTargets()
        {
            const string source =
                """
                using System;

                public static class EntryPoint
                {
                    public static void M(DerivedResource resource)
                    {
                        using (resource)
                        {
                        }
                    }
                }

                public class BaseResource : IDisposable
                {
                    public virtual void Dispose()
                    {
                        throw new ArgumentException();
                    }
                }

                public class DerivedResource : BaseResource
                {
                    public override void Dispose()
                    {
                        throw new InvalidOperationException();
                    }
                }

                public sealed class MoreDerivedResource : DerivedResource
                {
                    public override void Dispose()
                    {
                        throw new FormatException();
                    }
                }

                public sealed class SiblingResource : BaseResource
                {
                    public override void Dispose()
                    {
                        throw new NotSupportedException();
                    }
                }
                """;

            ExceptionFlowSummaryGraphTestRun run =
                ExceptionFlowSummaryGraphTestHelper.Build(
                    source,
                    "M");

            string[] targetTypeNames =
                GetDisposalEdges(run)
                    .Select(
                        static edge =>
                            GetTargetMethod(edge)
                                .ContainingType.Name)
                    .OrderBy(
                        static name =>
                            name,
                        StringComparer.Ordinal)
                    .ToArray();

            Assert.Equal(
                new[]
                {
                    "DerivedResource",
                    "MoreDerivedResource"
                },
                targetTypeNames);
        }

