        /// <summary>
        /// Ensures that an explicit IDisposable implementation becomes the
        /// runtime target of synchronous interface-based disposal.
        /// </summary>
        [Fact]
        public void IDisposableResource_UsesExplicitImplementation()
        {
            const string source =
                """
                using System;

                public static class EntryPoint
                {
                    public static void M(IDisposable resource)
                    {
                        using (resource)
                        {
                        }
                    }
                }

                public sealed class Resource : IDisposable
                {
                    void IDisposable.Dispose()
                    {
                        throw new InvalidOperationException();
                    }
                }
                """;

            ExceptionFlowSummaryGraphTestRun run =
                ExceptionFlowSummaryGraphTestHelper.Build(
                    source,
                    "M");

            ExceptionFlowSummaryCallEdge edge =
                Assert.Single(
                    GetDisposalEdges(run));

            IMethodSymbol targetMethod =
                GetTargetMethod(edge);

            Assert.Equal(
                "Resource",
                targetMethod.ContainingType.Name);

            Assert.Single(
                targetMethod.ExplicitInterfaceImplementations);

            AssertTargetException(
                run,
                edge,
                "InvalidOperationException");
        }

        /// <summary>
        /// Ensures that a derived type which reimplements IDisposable can use
        /// a different interface slot target from its base type.
        /// </summary>
        [Fact]
        public void IDisposableReimplementation_CreatesDerivedTarget()
        {
            const string source =
                """
                using System;

                public static class EntryPoint
                {
                    public static void M(BaseResource resource)
                    {
                        using (resource)
                        {
                        }
                    }
                }

                public class BaseResource : IDisposable
                {
                    public void Dispose()
                    {
                        throw new ArgumentException();
                    }
                }

                public sealed class DerivedResource :
                    BaseResource,
                    IDisposable
                {
                    void IDisposable.Dispose()
                    {
                        throw new InvalidOperationException();
                    }
                }
                """;

            ExceptionFlowSummaryGraphTestRun run =
                ExceptionFlowSummaryGraphTestHelper.Build(
                    source,
                    "M");

            ExceptionFlowSummaryCallEdge[] edges =
                GetDisposalEdges(run);

            Assert.Equal(
                2,
                edges.Length);

            AssertTargetException(
                run,
                GetEdgeForContainingType(
                    edges,
                    "BaseResource"),
                "ArgumentException");

            ExceptionFlowSummaryCallEdge derivedEdge =
                GetEdgeForContainingType(
                    edges,
                    "DerivedResource");

            Assert.Single(
                GetTargetMethod(derivedEdge)
                    .ExplicitInterfaceImplementations);

            AssertTargetException(
                run,
                derivedEdge,
                "InvalidOperationException");
        }

        /// <summary>
        /// Ensures that an IDisposable implementation selected from metadata
        /// is mapped back to its source declaration in a referenced project.
        /// </summary>
        [Fact]
        public void CrossCompilationIDisposable_UsesSourceImplementation()
        {
            const string dependencySource =
                """
                using System;

                namespace Dependency
                {
                    public sealed class Resource : IDisposable
                    {
                        public void Dispose()
                        {
                            throw new InvalidOperationException();
                        }
                    }
                }
                """;

            const string consumerSource =
                """
                using System;

                public static class EntryPoint
                {
                    public static void M(IDisposable resource)
                    {
                        using (resource)
                        {
                        }
                    }
                }
                """;

            ExceptionFlowSummaryGraphTestRun run =
                ExceptionFlowSummaryGraphProjectTestHelper.Build(
                    dependencySource,
                    consumerSource,
                    "M");

            ExceptionFlowSummaryCallEdge edge =
                Assert.Single(
                    GetDisposalEdges(run));

            IMethodSymbol targetMethod =
                GetTargetMethod(edge);

            Assert.Equal(
                "Resource",
                targetMethod.ContainingType.Name);

            Assert.False(
                targetMethod.DeclaringSyntaxReferences.IsDefaultOrEmpty);

            AssertTargetException(
                run,
                edge,
                "InvalidOperationException");
        }

