        /// <summary>
        /// Ensures that a typed catch filter is attached to every alternative
        /// disposal target edge.
        /// </summary>
        [Fact]
        public void TypedCatch_IsAppliedToEveryDisposalDispatchEdge()
        {
            const string source =
                """
                using System;

                public static class EntryPoint
                {
                    public static void M(BaseResource resource)
                    {
                        try
                        {
                            using (resource)
                            {
                            }
                        }
                        catch (ArgumentException)
                        {
                        }
                    }
                }

                public class BaseResource : IDisposable
                {
                    public virtual void Dispose()
                    {
                        throw new ArgumentException();
                    }
                }

                public sealed class DerivedResource : BaseResource
                {
                    public override void Dispose()
                    {
                        throw new InvalidOperationException();
                    }
                }
                """;

            ExceptionFlowSummaryGraphTestRun run =
                ExceptionFlowSummaryGraphTestHelper.Build(
                    source,
                    "M");

            INamedTypeSymbol argumentException =
                run.GetRequiredType(
                    "System.ArgumentException");

            ExceptionFlowSummaryCallEdge[] edges =
                GetDisposalEdges(run);

            Assert.Equal(
                2,
                edges.Length);

            Assert.All(
                edges,
                edge =>
                    Assert.True(
                        edge.Suppresses(
                            argumentException)));
        }

        /// <summary>
        /// Gets all synchronous and asynchronous disposal edges from the root
        /// summary.
        /// </summary>
        /// <param name="run">
        /// The completed graph test run.
        /// </param>
        /// <returns>The disposal edges in recorded order.</returns>
        private static ExceptionFlowSummaryCallEdge[] GetDisposalEdges(
            ExceptionFlowSummaryGraphTestRun run)
        {
            return run.RootSummary.CallEdges
                .Where(
                    static edge =>
                        edge.CallSiteStep.Kind is
                            ExceptionFlowPathStepKind.DisposeCall or
                            ExceptionFlowPathStepKind.DisposeAsyncCall)
                .ToArray();
        }

        /// <summary>
        /// Gets the uniquely matching disposal edge declared by one type.
        /// </summary>
        /// <param name="edges">
        /// The candidate disposal edges.
        /// </param>
        /// <param name="containingTypeName">
        /// The expected target containing-type name.
        /// </param>
        /// <returns>The matching disposal edge.</returns>
        private static ExceptionFlowSummaryCallEdge
            GetEdgeForContainingType(
                IEnumerable<ExceptionFlowSummaryCallEdge> edges,
                string containingTypeName)
        {
            return Assert.Single(
                edges.Where(
                    edge =>
                        string.Equals(
                            GetTargetMethod(edge)
                                .ContainingType.Name,
                            containingTypeName,
                            StringComparison.Ordinal)));
        }

        /// <summary>
        /// Gets the method symbol represented by one disposal edge target.
        /// </summary>
        /// <param name="edge">
        /// The disposal edge to inspect.
        /// </param>
        /// <returns>The required disposal method.</returns>
        /// <exception cref="InvalidOperationException">
        /// Thrown when the edge target is not a method symbol.
        /// </exception>
        private static IMethodSymbol GetTargetMethod(
            ExceptionFlowSummaryCallEdge edge)
        {
            return edge.Target.Symbol as IMethodSymbol ??
                   throw new InvalidOperationException(
                       "The disposal edge target was not a method.");
        }

        /// <summary>
        /// Ensures that one disposal target summary contains exactly one
        /// source with the expected exception type.
        /// </summary>
        /// <param name="run">
        /// The completed graph test run.
        /// </param>
        /// <param name="edge">
        /// The edge whose target summary should be inspected.
        /// </param>
        /// <param name="exceptionTypeName">
        /// The expected simple exception type name.
        /// </param>
        private static void AssertTargetException(
            ExceptionFlowSummaryGraphTestRun run,
            ExceptionFlowSummaryCallEdge edge,
            string exceptionTypeName)
        {
            ExceptionFlowSummary targetSummary =
                run.GetRequiredSummary(
                    edge.Target);

            ExceptionFlowSummarySource source =
                Assert.Single(
                    targetSummary.Sources);

            Assert.Equal(
                exceptionTypeName,
                source.ExceptionType.Name);
        }
    }
